text:
{
  "design": {
    "theme": "playground",
    "picture_style": "photo"
  },
  "flow": [
    {
      "slide": 1,
      "does": "Recall familiar animals",
      "look_at": {"kind": "picture", "shows": "A cow, sheep, hen and dog"},
      "teaches": []
    },
    {
      "slide": 2,
      "does": "Share the learning goals",
      "look_at": {"kind": "none", "shows": null},
      "teaches": []
    },
    {
      "slide": 3,
      "does": "Teach cow–calf and sheep–lamb names",
      "look_at": {"kind": "picture", "shows": "Two adult animals beside their young"},
      "teaches": [1]
    },
    {
      "slide": 4,
      "does": "Teach hen–chick and dog–puppy names",
      "look_at": {"kind": "picture", "shows": "Two adult animals beside their young"},
      "teaches": [1]
    },
    {
      "slide": 5,
      "does": "Model matching and naming",
      "look_at": {"kind": "picture", "shows": "A cow beside a calf"},
      "teaches": [1]
    },
    {
      "slide": 6,
      "does": "Try matching and naming independently",
      "look_at": {"kind": "picture", "shows": "Four adults and their young in a mixed order"},
      "teaches": [1]
    },
    {
      "slide": 7,
      "does": "Correct the idea that young look exactly like adults",
      "look_at": {"kind": "picture", "shows": "A fluffy chick beside a feathered hen"},
      "teaches": [2]
    },
    {
      "slide": 8,
      "does": "Teach changes as a chick grows",
      "look_at": {"kind": "picture-sequence", "shows": "A chick, a growing young chicken and an adult hen"},
      "teaches": [2]
    },
    {
      "slide": 9,
      "does": "Model describing two changes",
      "look_at": {"kind": "picture", "shows": "A small chick and a larger adult hen"},
      "teaches": [2]
    },
    {
      "slide": 10,
      "does": "Try describing the same changes",
      "look_at": {"kind": "picture", "shows": "Another small chick and adult hen"},
      "teaches": [2]
    },
    {
      "slide": 11,
      "does": "Check understanding of growth",
      "look_at": {"kind": "none", "shows": null},
      "teaches": [2]
    },
    {
      "slide": 12,
      "does": "Apply learning to a new farm sign",
      "look_at": {"kind": "picture", "shows": "A calf beside a cow and a chick beside a hen"},
      "teaches": [1, 2]
    }
  ],
  "title": {
    "template": "title",
    "heading": "Animals and their young",
    "lead": "Name an animal you can see.",
    "picture": {
      "shows": "Four separate photographs of a cow, sheep, hen and dog",
      "must_see": ["adult dairy cow", "adult woolly sheep", "adult brown hen", "adult pet dog"],
      "subject": "generic"
    }
  },
  "slides": [
    {
      "template": "compare",
      "heading": "Say the names",
      "columns": [
        {
          "label": "Cow and calf",
          "text": "A calf is a young cow.",
          "picture": {
            "shows": "An adult cow standing beside a much smaller calf",
            "must_see": ["adult dairy cow", "small young calf"],
            "subject": "generic"
          }
        },
        {
          "label": "Sheep and lamb",
          "text": "A lamb is a young sheep.",
          "picture": {
            "shows": "An adult sheep standing beside a smaller lamb",
            "must_see": ["adult woolly sheep", "small young lamb"],
            "subject": "generic"
          }
        }
      ]
    },
    {
      "template": "compare",
      "heading": "Say the names",
      "columns": [
        {
          "label": "Hen and chick",
          "text": "A chick is a young chicken.",
          "picture": {
            "shows": "An adult hen standing beside a fluffy chick",
            "must_see": ["adult brown hen", "small fluffy chick"],
            "subject": "generic"
          }
        },
        {
          "label": "Dog and puppy",
          "text": "A puppy is a young dog.",
          "picture": {
            "shows": "An adult dog sitting beside a smaller puppy",
            "must_see": ["adult pet dog", "small young puppy"],
            "subject": "generic"
          }
        }
      ]
    },
    {
      "template": "visual-text",
      "heading": "Match and name",
      "lead": "This is a cow. Its young is a calf.",
      "points": [
        {"label": "Match", "text": "The cow and calf go together."}
      ],
      "figure": {
        "shows": "An adult cow beside a calf with similar markings",
        "must_see": ["large adult cow", "small young calf", "similar coat markings"],
        "subject": "generic"
      }
    },
    {
      "template": "question-set",
      "heading": "Find the pairs",
      "questions": [
        "Find the cow and its young. Name both.",
        "Match the other animals. Name each pair."
      ],
      "instruction": "Point to each pair and say its names.",
      "picture": {
        "shows": "Eight separate photographs in two rows: adults cow, sheep, hen, dog above young puppy, chick, calf, lamb; no connecting lines",
        "must_see": ["adult dairy cow", "adult woolly sheep", "adult brown hen", "adult pet dog"],
        "subject": "generic"
      }
    },
    {
      "template": "compare",
      "heading": "Not exactly the same",
      "columns": [
        {
          "label": "Chick",
          "text": "Small, with soft fluff.",
          "picture": {
            "shows": "A newly hatched fluffy yellow chick",
            "must_see": ["tiny yellow chick", "soft fluffy covering", "short small wings"],
            "subject": "generic"
          }
        },
        {
          "label": "Hen",
          "text": "Bigger, with adult feathers.",
          "picture": {
            "shows": "A full-grown brown hen with clearly visible wing and tail feathers",
            "must_see": ["large brown hen", "long tail feathers", "layered wing feathers"],
            "subject": "generic"
          }
        }
      ]
    },
    {
      "template": "picture-sequence",
      "heading": "A chick grows",
      "sequence": [
        {
          "shows": "A newly hatched female chick with fluffy down; adult wing and tail feathers are not yet present",
          "must_see": ["small fluffy chick", "short tiny wings"],
          "subject": "generic",
          "caption": "Small and fluffy"
        },
        {
          "shows": "A larger young female chicken with emerging wing feathers and some fluff; full adult plumage is not yet present",
          "must_see": ["larger young chicken", "new wing feathers", "remaining soft fluff"],
          "subject": "generic",
          "caption": "Feathers grow"
        },
        {
          "shows": "A full-grown hen with adult wing and tail feathers and no chick-like fluffy covering",
          "must_see": ["full-grown adult hen", "layered wing feathers", "long tail feathers"],
          "subject": "generic",
          "caption": "An adult hen"
        }
      ]
    },
    {
      "template": "visual-text",
      "heading": "Describe the changes",
      "lead": "This chick grows into a hen.",
      "points": [
        "It gets bigger.",
        "It grows adult feathers."
      ],
      "figure": {
        "shows": "A small fluffy female chick beside an adult hen, shown at the same scale",
        "must_see": ["small fluffy chick", "much larger hen", "adult wing feathers"],
        "subject": "generic"
      }
    },
    {
      "template": "question-set",
      "heading": "What changes?",
      "questions": [
        "How does its size change?",
        "How does its covering change?"
      ],
      "instruction": "Say two changes as this chick grows.",
      "picture": {
        "shows": "A small fluffy female chick beside a full-grown white hen, shown at the same scale",
        "must_see": ["small fluffy chick", "large white hen", "adult tail feathers"],
        "subject": "generic"
      }
    },
    {
      "template": "hinge",
      "heading": "Choose one",
      "stem": "As a chick grows, what happens?",
      "options": [
        "Bigger; adult feathers grow",
        "Bigger; stays fluffy",
        "Same size; adult feathers grow"
      ],
      "correct": 1
    },
    {
      "template": "question-set",
      "heading": "Make a farm sign",
      "questions": [
        "Name the adult animals and their young.",
        "Say two ways this chick will change.",
        "What will change? What will stay the same?"
      ],
      "instruction": "Tell a partner what your sign should say.",
      "picture": {
        "shows": "A new farm scene with a calf beside a cow and a fluffy female chick beside a hen",
        "must_see": ["cow and calf", "hen and chick", "adult hen feathers", "small fluffy chick"],
        "subject": "generic"
      }
    }
  ]
}
